/**
 * Weapon painting element zones (Top-Choice renderer slice,
 * 2026-11-11) — GENERATED by scripts/derive-weapon-zones.py;
 * do not edit by hand. Re-run the script instead.
 *
 * Per weapon base (type x manufacturer stem): the source
 * RGBs of the painting's element GLOW ZONE — the chamber
 * window (beam: window + exposed spine channel to the
 * emitter) — classified per base by Wave 2's zone-proof
 * method (HSV clustering on palette entries; the per-base
 * parameters are authored in the script), plus, per
 * element, the palette swap table that re-lights the zone:
 * each glow entry remapped core->accent by its relative
 * luminance (the zone proof's operation). Body and trim
 * entries never appear in a table, so a swap leaves them
 * byte-identical by construction.
 */
import type { Element } from "@/types/game";
import { Element as ElementEnum } from "@/types/game";

